{
  "name": "@flexapp/opencode-plugin-litellm",
  "version": "0.9.0",
  "description": "LiteLLM provider plugin for opencode: model discovery, readable model names, and per-session upstream routing",
  "type": "module",
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/flexapp/opencode-plugin-litellm.git"
  },
  "main": "./src/plugin.ts",
  "exports": {
    ".": "./src/plugin.ts",
    "./server": "./src/plugin.ts",
    "./tui": "./dist/tui.js",
    "./rpc": "./src/route-rpc.ts"
  },
  "files": [
    "src",
    "dist",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "litellm"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "build": "bun build src/tui.ts --outfile dist/tui.js --target bun --format esm --external @opencode-ai/plugin --external @opencode/plugin --external @opencode/plugin/tui --external @opencode/plugin/rpc --external @opentui/core --external @opentui/solid --external solid-js",
    "prepare": "bun run build",
    "prepublishOnly": "bun run typecheck"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.15.13",
    "@opencode-ai/sdk": "1.15.13",
    "@opencode/plugin": "2.0.24"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.2.16",
    "@opentui/solid": ">=0.2.16",
    "solid-js": ">=1.9.12"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@types/node": "24.12.2",
    "typescript": "5.8.2",
    "@opentui/core": "0.5.14",
    "@opentui/solid": "0.5.14",
    "solid-js": "1.9.15"
  }
}
